    philosophy: 'Amos, paysan et éleveur de troupeaux devenu prophète, exprime la vision divine de la justice sociale avec une image d\'une puissance incomparable. La justice ne doit pas être intermittente — un ruisseau en été — mais pérenne comme un torrent qui ne tarit pas. Cette métaphore aquatique de la justice est l\'une des plus citées dans l\'histoire des droits humains. La Torah exige une société où la justice est structurelle, pas charitable.',
