    french: 'Je vous donnerai un cœur nouveau — et j\'instillerai en vous un esprit nouveau — j\'ôterai le cœur de pierre.',
    philosophy: 'Ézéchiel prophétise la transformation la plus profonde qui soit : non pas une réforme extérieure mais une transplantation intérieure. Le "lev habasar" — cœur de chair — est le cœur capable de ressentir, de s\'émouvoir, d\'aimer. Le cœur de pierre est le cœur fermé, rationalisé, protégé de la blessure mais aussi de la joie. La promesse divine est qu\'un jour, la sensibilité spirituelle ne sera plus effort mais nature.',
