    hebrew: 'יִרְאַת שָׁמַיִם צְרִיכָה לְהֵרָגֵשׁ — לֹא רַק לְהֵיוָדַע׃',
    source: 'Rabbi Israel Salanter, Iggeret HaMussar',
    french: 'La crainte du Ciel doit être ressentie — pas seulement connue.',
    philosophy: 'Cette distinction est au cœur du projet mussar : la transformation ne s\'arrête pas à la tête. Israel Salanter observait que les hommes les plus érudits pouvaient être enclins à la colère, à l\'arrogance ou à la petitesse. La yirat shamayim authentique se manifeste dans le comportement spontané, les réactions instinctives, les moments de crise. C\'est pourquoi le Mussar préconise un travail quotidien et systématique sur les traits de caractère (middot).',
    philosophyAuthor: 'Sfat Emet',
