    philosophy: 'Simcha Zissel Ziv (1824-1898), le "Sabba de Kelm", enseignait que l\'émet est la vertu architecturale : sans elle, toutes les autres sont fragiles. On peut être "généreux" pour être admiré, "humble" par calcul — mais si l\'émet manque, ces vertus sont des masques. La vérité commence par l\'honnêteté avec soi-même : voir clairement ses motivations réelles, ses failles réelles, sa réalité réelle. Cette lucidité est le point de départ de toute croissance spirituelle.',
