    hebrew: 'כָּל מְצִיאוּת הָאָדָם בָּעוֹלָם — תַּלְמוּד תּוֹרָה — תְּפִלָּה — וּגְמִילוּת חֲסָדִים׃',
    source: 'Talmud Bavli, Shabbat 127a',
