    philosophy: 'Ce passage talmudique énumère les trois piliers de l\'existence juive active. L\'étude (talmud Torah) engage l\'intellect dans la rencontre avec la sagesse divine. La prière (tefillah) engage le cœur dans la relation personnelle avec Dieu. Les actes de bonté (gemilut hasadim) incarnent dans le monde concret ce que Torah et prière ont approfondi. Ces trois ne sont pas des obligations concurrentes mais un trépied — chacun est incomplet sans les deux autres.',
