    french: 'Le sceau du Saint, béni soit-Il, est la vérité.',
    philosophy: 'Le Kotzker fit de cet enseignement talmudique le centre de toute sa vie spirituelle. Si Dieu est Vérité, alors toute relation authentique avec Dieu exige la vérité absolue. Le Kotzker ne pouvait tolérer la fausse piété, le sentiment religieux de performance, la sainteté jouée pour les autres. Il exigeait une brutalité totale envers soi-même : voir sans illusion, agir sans masque. Cette radicalité lui valut un isolement de 20 ans — preuve de sa cohérence.',
