    french: 'Je sais que mon Rédempteur est vivant — et qu\'Il se lèvera le dernier sur la poussière.',
    philosophy: 'Job, après avoir tout perdu, exprime une foi d\'une profondeur extraordinaire. Non pas que la souffrance soit expliquée — elle ne l\'est jamais dans le Livre de Job — mais que malgré elle, la confiance dans le Rédempteur demeure. Ce verset est lu à la lumière de la résurrection dans certaines traditions, mais sa force première est humaine : même depuis le fond du désespoir, une lumière de confiance peut persister. La foi n\'est pas l\'absence de souffrance — elle existe à l\'intérieur de la souffrance.',
